    self_pos = observation.get("self_position") or (0, 0)
    opp_pos = observation.get("opponent_position") or self_pos
    sx, sy = self_pos[0], self_pos[1]
    ox, oy = opp_pos[0], opp_pos[1]
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

